mapper.select:
SELECT id, name, price, remark, sold, created_at, updated_at, user_id
FROM tool
WHERE deleted = 0

    AND user_id = #{dto.userId}


    AND name LIKE CONCAT('%', #{dto.name}, '%')


    AND price >= #{dto.minPrice}


    AND price <= #{dto.maxPrice}


    AND sold = #{dto.sold}

ORDER BY created_at DESC
